"ctx": "uit een Nederlandse krant, 24 juni 2016: De Britse bevolking sprak zich gisteren tijdens het referendum uit voor een vertrek uit de Europese Unie (EU). Deze aankondiging van de Brexit leidde tot een koersdaling van het Britse pond als gevolg van het gedrag van beleggers. Verder heeft een aantal banken aangekondigd hun hoofdvestiging van Londen naar het Europese vasteland te gaan verplaatsen. De koersdaling van het Britse pond ten opzichte van de euro en de dollar heeft gevolgen voor de internationale handel van Groot Brittannië (GB). Er wordt bijvoorbeeld verwacht dat meer buitenlandse toeristen een weekend naar Londen zullen boeken. Daarnaast wordt verwacht dat de concurrentiepositie van onder meer Nederlandse agrariërs zal verslechteren, terwijl de concurrentiepositie van Britse agrariërs zal verbeteren. De koersdaling kan ook gevolgen hebben voor de inflatie in GB, die waarschijnlijk zal toenemen.",
"q": "Leg uit dat door het gedrag van beleggers de Brexit kan leiden tot een koersdaling van het Britse pond.",
