"ctx": "Een econome reageert op de ontwikkelingen: “Een vaste wisselkoers kan bij een tekort op de betalingsbalans zowel gunstig als ongunstig zijn. Het is gunstig omdat de inflatie op ons eiland laag blijft en het is ongunstig omdat Amerikaanse toeristen niet kunnen profiteren van een koersvoordeel.”",
