"model": "Een voorbeeld van een juiste uitleg is:\n• Door het tekort op de betalingsbalans is het aanbod van AWG’s groter dan de vraag. Bij een flexibele wisselkoers zou de waarde van de AWG dalen (ten opzichte van de US$) waardoor Aruba goedkoper wordt voor Amerikaanse toeristen (1p)\n• Door de vaste wisselkoers ten opzichte van de US$ zijn de Amerikaanse toeristen niet goedkoper uit (1p)",
