"model": "gas Een voorbeeld van een juiste toelichting is: Het gastarief bij het 3 jaar-vast-contract (Zekur) is hoger dan bij het variabel contract (Free) zodat de energieleverancier blijkbaar anticipeert op een tariefsverhoging.",
