"q": "Gebruik de inleidende tekst en het krantenbericht.\nMaak van de onderstaande tekst een economisch juiste redenering.\n\nDe wettelijke verplichting om verzekerd te zijn voor kosten van de basiszorg is een vorm van …(1)…. De lagere gemiddelde kosten van Anderzorg kunnen het gevolg zijn van een stijging van …(2)…. Verzekerden die veel claimen hebben een …(3)… van een verlaging van het eigen risico. Kies uit: bij (1) collectieve dwang / zelfbinding bij (2) het aantal verzekerden / de toegevoegde waarde bij (3) voordeel / nadeel vervolg krantenbericht, 14 november 2017: Op de opmerking van Anderzorg om via een verlaging van het eigen risico de solidariteit tussen ‘goede’ en ‘slechte’ risico’s te bevorderen, reageert gezondheidseconoom Harry Klein “Dat is naar mijn mening niet de reden van de verlaging van het eigen risico. De reden is dat Anderzorg en Beterzorg een gevangenendilemma ervaren.”",
