"ctx": "uit een krant, december: In Noorwegen is een botercrisis ontstaan, waarbij de prijs van roomboter uitzonderlijk hoog is geworden. Het aanbod is in handen van één producent, de zuivelondernemer Tine. De productiekosten van Tine zijn gestegen, doordat er na de recente natte zomer minder veevoer van goede kwaliteit was, en dus minder aanbod van melk en een hogere melkprijs. De prijsstijging van roomboter is nog versterkt doordat de Noren tijdens kerst en de jaarwisseling veel lekkernijen bereiden met roomboter. Het importeren van roomboter is geen echt alternatief, omdat Noorwegen de invoer van roomboter met een hoog tarief belast.",
"q": "Citeer de zin uit het krantenbericht waaruit blijkt dat de vraagzijde van de roombotermarkt van invloed is op de prijsstijging van roomboter.",
"model": "“De prijsstijging van roomboter is nog versterkt doordat de Noren tijdens kerst en de jaarwisseling veel lekkernijen bereiden met roomboter.”",
