"q": "Leg uit dat het Belgische systeem van loonaanpassing kan leiden tot een verslechtering van de internationale concurrentiepositie van de Belgische ondernemers.",
"model": "Een voorbeeld van een juist antwoord is:\n• Als de lonen in België ten opzichte van de arbeidsproductiviteit sneller stijgen dan in andere landen (1p)\n• dan stijgen de loonkosten per product van Belgische producten (en daarmee de verkoopprijs) sneller dan die in andere landen (en als gevolg kunnen de Belgische ondernemers slechter concurreren) (1p)",
