"model": "Een voorbeeld van een juist antwoord is:\n• Bij de verlaagde prijs is (door een verschuiving langs de vraaglijn) de gevraagde hoeveelheid groter dan bij de evenwichtsprijs, en is (door een verschuiving langs de aanbodlijn) de aangeboden hoeveelheid kleiner dan bij de evenwichtsprijs, en (1p)\n• beide wijzigingen samen leiden ertoe dat de gevraagde hoeveelheid groter is dan de aangeboden hoeveelheid (1p)",
