"q": "Geef een voorbeeld van een manier waarop ondernemers die geld willen uitlenen, de asymmetrische informatie hierbij kunnen beperken.",
"model": "Voorbeelden van een juist antwoord zijn: - informatie opvragen over de kredietwaardigheid van de ondernemer\ndie wil lenen - de boekhouding van de ondernemer die wil lenen controleren - voorwaarden stellen aan het verstrekken van informatie over de\nbedrijfsvoering / de bedrijfsrisico’s van de ondernemer die wil lenen",
