"ctx": "Vanaf 2008 heeft de overheid besloten dat ook andere vervoerders dan de NS passagiersvervoer in Nederland mogen aanbieden. Daartoe heeft de overheid Nederland in regio’s ingedeeld. Per regio verkoopt de overheid één concessie (vergunning) om in die regio passagiersvervoer te verzorgen. De NS en andere vervoersmaatschappijen kunnen bieden op een concessie (vergunning) om in die regio passagiersvervoer te verzorgen. De prijs van de concessie is een vergoeding voor het gebruik van het eerder aangelegde spoorwegennet.",
