"ctx": "De overheid van een land heeft het klimaatakkoord van Parijs getekend. De overheid heeft daarom het besluit genomen om de eigen gasproductie versneld af te bouwen en gezinnen en bedrijven in het land te stimuleren om het verbruik van gas sterk te verminderen. Voor de overheid leidt de terugval in aardgasinkomsten tot een financiële tegenvaller op de begroting van miljarden euro’s per jaar. Zonder extra maatregelen ontstaat hierdoor een overheidstekort.",
