"nr": 6,
"ctx": "Uit een krant: De Nederlandse overheid heeft het plan om een vliegbelasting van € 7,50 per vliegticket in te voeren voor alle vluchten vanaf een Nederlandse luchthaven: de vliegtaks. De luchtvaartmaatschappijen berekenen de heffing door in de eindprijs van een vliegticket en moeten vervolgens per verkocht ticket € 7,50 afdragen aan de belastingdienst. Het doel van de vliegtaks is om het vliegen voor passagiers minder aantrekkelijk te maken en zo de uitstoot van broeikasgassen te verlagen. Een onderzoeksbureau analyseert de effecten van de vliegtaks op het milieu en trekt de conclusie dat deze op de korte termijn verwaarloosbaar klein zijn als bij elke vlucht alleen de bezettingsgraad van de vliegtuigen zal dalen. noot bezettingsgraad = het feitelijke aantal bezette stoelen afgezet tegen het beschikbare aantal stoelen",
"q": "Geef een verklaring voor de conclusie van het onderzoeksbureau.",
