"ctx": "Van de website van Deel-Kar.nl: Auto’s zijn duur en staan veruit het grootste deel van hun leven stil. Waarom dan niet je eigen auto delen met een ander, als je hem zelf niet gebruikt? Dat leidt tot minder autobezit en dat is goed voor het milieu. Bied uw auto aan via de app, waar u uw auto kunt omschrijven en kunt aangeven welke vergoeding u vraagt aan de huurder. Natuurlijk is uw auto goed verzekerd via onze partner Deel-Zeker! Of vul uw postcode in en bekijk welke auto’s u kunt huren en welke vergoeding door de autobezitter aan u wordt gevraagd. Voor elke transactie die via onze app of website tot stand komt betaalt de de autobezitter € 10 aan Deel-Kar.nl als vergoeding voor de bemiddeling. Milieuorganisaties stellen dat dankzij het initiatief van Deel-Kar.nl: - enerzijds de milieuvervuiling via afnemend autobezit kan afnemen, maar dat - anderzijds de milieuvervuiling door het initiatief van Deel-Kar.nl juist ook kan toenemen.",
