"ctx": "Econoom Charlotte Brouwer zegt over Deel-Kar.nl: “De winstgevendheid van Deel-Kar.nl wordt negatief beïnvloed door asymmetrische informatie bij zowel de verhuurder als de huurder van een deelauto.",
