"ctx": "Woningbezitters mogen de betaalde hypotheekrente aftrekken van de inkomstenbelasting. Dit belastingvoordeel bevordert eigenwoningbezit, en belemmert een goed functionerende verhuurmarkt. De overheid wil een evenwichtige woningmarkt bevorderen, en past daarom de tarieven van de hypotheekrenteaftrek aan. Zo wordt het marginale belastingtarief waartegen de hypotheekrente maximaal kan worden afgetrokken geleidelijk afgebouwd van 49,50% naar 37,05%. belastbaar inkomen marginaal tarief hypotheekrenteaftrek nu na afbouw € 0 - € 69.398 37,05% 37,05% € 69.399 en hoger 49,50% 37,05% Een econoom doet naar aanleiding van de tariefaanpassing twee uitspraken: Uitspraak 1: “Door de tariefaanpassing wordt de secundaire inkomensverdeling gelijker.” Uitspraak 2: “Op de lange termijn kan de tariefaanpassing bijdragen aan de betaalbaarheid van koopwoningen.”",
"q": "Gebruik uitspraak 2 van de econoom.\nLeg uit dat de tariefaanpassing via de vraagzijde van de woningmarkt kan leiden tot een daling van de verkoopprijs van koopwoningen.",
"model": "Een voorbeeld van een juist antwoord is:\n• Door de tariefaanpassing wordt het financieren van een koopwoning duurder. (1p)\n• Hierdoor daalt de vraag naar koopwoningen (bij elke prijs) en dit leidt (bij gelijkblijvend aanbod) tot een daling van de verkoopprijs van woningen. (1p)",
