"model": "Een voorbeeld van een juist antwoord is:\n• Bij het uitstel van verlaging van pensioenuitkeringen blijven de tekorten, die later worden gecompenseerd door uitkeringen alsnog te verlagen / premies te verhogen. (1p)\n• De kosten komen zo voor rekening voor de jongere generatie en hierdoor wordt de oudere generatie ontzien. (1p)",
