"ctx": "Nederland heeft een wettelijk minimumuurloon voor alle werknemers van 15 jaar en ouder. In een talkshow debatteren twee economen over de gevolgen van het verhogen van dit minimumuurloon. Econoom 2: ‘Een hoger minimumuurloon kan leiden tot een verslechtering van de Nederlandse internationale concurrentiepositie’. Econoom 1: ‘Een hoger minimumuurloon kan leiden tot meer economische groei’.",
"q": "Leg de uitspraak van econoom 2 uit.",
