"ctx": "Aan het einde van het kwartaal zijn de aandelenkoersen weer gestegen. Een belegger koopt op 31 januari 4.000 aandelen ASML en 6.000 aandelen ING. Op 1 april verkoopt de belegger deze aandelen weer. De aandelenkoersen zijn weergegeven in onderstaande tabel. Nederlandse aandelenkoersen op de beurs in de VS aandeel koers ($) 31 januari koers ($) 1 april ASML 149,40 187,50 ING 14,61 18,32",
"q": "Bereken de winst van de belegger in procenten van het aankoopbedrag.",
"model": "Een voorbeeld van een juiste berekening is:\n• aankoop: 4.000 × 149,40 + 6.000 × 14,61 $ 685.260 verkoop: 4.000 × 187,50 + 6.000 × 18,32 $ 859.920 winst $ 174.660 (1p)\n• winst in procenten van aankoop: $ 174.660 / $ 685.260 x 100% = 25,49% (1p)",
"pnt": 2
