"q": "Leg uit waarom de overheid een vereveningsfonds instelt voor de basiszorgverzekering.",
"model": "Een voorbeeld van een juiste uitleg is:\n• De acceptatieplicht kan ertoe leiden dat de ene verzekeraar relatief veel slechte risico’s heeft, terwijl andere verzekeraars juist relatief veel goede risico’s hebben. (1p)\n• Door het vereveningsfonds worden deze verschillen aan schade-uitkeringen verminderd / wordt voorkomen dat verzekeraars met alleen maar slechte risico’s failliet gaan. (1p)",
