"model": "Een voorbeeld van een juist antwoord is:\n• Het overheidstekort leidt tot een toename van de overheidsschuld die toekomstige verplichtingen (rentelasten en aflossing) veroorzaakt. (1p)\n• Deze verplichtingen moeten (uiteindelijk) met toekomstige belastingontvangsten worden betaald. (1p)",
