"ctx": "Fietsverzekeraar Fietsgarant heeft 10.000 diefstalverzekeringen voor fatbikes afgesloten. De gemiddelde verzekerde waarde is € 1.600. Het totale schadebedrag per jaar is € 9.600.000.",
"q": "Bereken de kans op diefstal.",
"model": "Voorbeelden van een juiste berekening zijn: - De kans op diefstal is: (€ 9.600.000 / 10.000) € 1.600 = 0,6 - De kans op diefstal is: (10.000 € 9.600.000 x € 1.600) = 0,6 Opmerking Antwoorden met een berekening in procenten of een ratio kan de maximale score opleveren.",
