"ctx": "Het Centraal Planbureau (CPB) onderzoekt het effect van het belastingstelsel voor verschillende inkomensgroepen in Nederland. Het CPB kijkt hierbij naar het gemiddelde bruto-jaarinkomen, de betaalde belastingen, sociale premies en het gemiddeld belastingtarief.",
"q": "Maak van de onderstaande zinnen een economisch juiste tekst.\n\n- Er is een progressief belastingstelsel. Een stijging van het inkomen leidt tot een …(1)… van het gemiddeld belastingtarief. Secundaire inkomens zullen …(2)…. - Lage inkomens consumeren een groter deel van hun inkomen dan hoge inkomens. Hierdoor dragen lage inkomens een …(3)… deel van hun inkomen af aan …(4)… belastingen, zoals btw en accijnzen. - Bij de premies sociale zekerheid betaalt iedereen hetzelfde percentage over het belastbaar inkomen tot € 38.000. Over het inkomen daarboven wordt geen premie betaald. Dit betekent dat er sprake is van een …(5)… premiestelsel. Kies uit: bij (1) daling / stijging bij (2) denivelleren / nivelleren bij (3) groter / kleiner bij (4) directe / indirecte bij (5) degressief / progressief / proportioneel",
"model": "(1) stijging (2) nivelleren (3) groter (4) indirecte (5) degressief\n(1) en (2) juist 1 (3) en (4) juist 1 (5) juist (1p)",
