"ctx": "Het bedrijf Safetybell heeft een patent op de productie (en verkoop) van video-deurbellen. Deze deurbellen hebben een videocamera en een ingebouwd alarm, wat bijdraagt aan een gevoel van veiligheid. Safetybell streeft naar maximale winst. Tabel 1 Financiële gegevens Safetybell prijsafzetfunctie GO = -50Q + 400 gemiddelde variabele kosten (in €) GVK = 12,5Q + 100 totale constante kosten (in €) TCK = 600.000 P (=GO) verkoopprijs in € Q afzet in tienduizenden stuks. Figuur 1 Marktsituatie van Safetybell De overheid vindt dat de videodeurbellen zorgen voor een betere veiligheid en dat daardoor de maatschappelijke kosten als gevolg van criminaliteit dalen. De overheid overweegt een subsidie te geven per videodeurbel aan de laagste inkomensgroepen.",
"q": "Is hier sprake van degressief, proportioneel of progressief variabele kosten? Leg je antwoord uit.",
"model": "Een voorbeeld van een juist antwoord is: De MK-lijn heeft een stijgend verloop, wat betekent dat ook de gemiddelde variabele kosten toenemen per extra geproduceerd product waardoor er sprake is van progressief variabele kosten.",
