"ctx": "Een econoom heeft de verwachtingen over het pensioenstelsel uitgewerkt in een model voor de komende 20 jaar (figuur 1). Figuur 1 Pensioenmodel econoom (2024–2044) Bij het opstellen van het model is de econoom uitgegaan van onderstaande aannames over de periode 2025-2044: a jaarlijkse inflatie = 2%; b jaarlijkse reële economische groei = 0,5%; c jaarlijkse rendement pensioenvermogen = 3,5%; d de premiedruk (premie als % van het bbp) blijft gelijk; e het aantal premieplichtingen (actieven) blijft gelijk; f de kapitaalinkomens blijven gelijk.",
