"ctx": "In 2023 stijgt het nationaal inkomen van Kroatië ten opzichte van 2022 met 3,4% tot € 68,9 miljard. Gebruik figuur 3",
"q": "Toon met een berekening aan of toetreding tot de EU een positief effect heeft gehad op de exportwaarde van Kroatië.",
