"ctx": "De toetreding tot de EMU heeft voor Kroatië nog meer effecten gehad zoals de invoering van de mededingingswet. Deze wet bevat regels ten aanzien van kartels en misbruik van een economische machtspositie. De mededingingsautoriteit handhaaft de mededingingswet.",
