"model": "Een juist antwoord bevat in relatie tot de context:\n• een uitleg dat de mededingingswet niet rivaliserend is. (1p)\n• een uitleg dat de mededingingswet niet uitsluitbaar is. (1p)\nEen voorbeeld van een juist antwoord is:\n• Niet rivaliserend: als de wet één persoon / onderneming beschermt, beschermt hij ook andere personen / ondernemingen. (1p)\n• Niet uitsluitbaar: de wet geldt voor iedereen. Het kan niet dat bepaalde personen / ondernemingen worden uitgesloten van handhaving. (1p)",
